    );
    process.exit(1);
  }

  // Configure the SDK
  configure({ accessToken, baseURL: apiUrl });

  // Read trial_id to construct the task ID
  const trialId = fs.readFileSync("/logs/trial_id", "utf-8").trim();
  const taskId = `ai-content-generator-${trialId}`;

